private static readonly MAX_RETRIES = 3;
private static readonly BASE_DELAY_MS = 250;
private static readonly MAX_DELAY_MS = 8_000;

async request<T>(path: string, opts: RequestOptions = {}): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    const res = await this.fetchImpl(`${API_BASE}${path}`, {
      method: opts.method ?? 'GET',
      headers: this.buildHeaders(opts),
      body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
      signal: AbortSignal.timeout(opts.timeoutMs ?? DEFAULT_TIMEOUT_MS),
    });

    if (res.status === 429 && attempt < PaymentsClient.MAX_RETRIES) {
      await this.sleep(this.retryDelayMs(attempt, res.headers.get('retry-after')));
      continue;
    }

    if (!res.ok) {
      throw new PaymentsError(`payments request failed with ${res.status}`, res.status, await res.text());
    }

    return (await res.json()) as T;
  }
}

/** Retry-After (seconds) wins when the server sends it; otherwise full-jitter exponential backoff. */
private retryDelayMs(attempt: number, retryAfter: string | null): number {
  const seconds = retryAfter === null ? Number.NaN : Number(retryAfter);
  if (Number.isFinite(seconds) && seconds >= 0) {
    return Math.min(seconds * 1000, PaymentsClient.MAX_DELAY_MS);
  }
  const ceiling = Math.min(PaymentsClient.BASE_DELAY_MS * 2 ** attempt, PaymentsClient.MAX_DELAY_MS);
  return Math.round(ceiling / 2 + Math.random() * (ceiling / 2));
}

private sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

